-- Ids are generated by the database in insert order, starting at 1.
-- The foreign keys below rely on that order.

-- animal_id 1 = REG001, 2 = REG002
INSERT INTO animal (arrival_date, weight, origin, registration_number)
VALUES ('2026-09-18 07:30', 120.5, 'FARM001', 'REG001'),
       ('2026-09-18 08:15', 132, 'FARM002', 'REG002');

-- part_type_id 1 = Ham, 2 = Rib
INSERT INTO parttype (name)
VALUES ('Ham'),
       ('Rib');

-- tray_id 1 = Ham tray, 2 = Rib tray
INSERT INTO tray (max_weight_capacity, current_weight, part_type_id)
VALUES (50, 40, 1),
       (50, 35, 2);

-- Both animals have parts in both trays
INSERT INTO part (weight, animal_id, tray_id, part_type_id)
VALUES (20, 1, 1, 1),
       (20, 2, 1, 1),
       (15, 1, 2, 2),
       (20, 2, 2, 2);

-- product_type_id 1 = Ham Package, 2 = Half Animal
INSERT INTO producttype (name)
VALUES ('Ham Package'),
       ('Half Animal');

-- product_id 1 = Ham Package, 2 = Half Animal
INSERT INTO product (packing_date, product_type_id)
VALUES ('2026-09-18 14:00', 1),
       ('2026-09-18 15:30', 2);

-- Product 1 comes from the Ham tray, product 2 from both trays
INSERT INTO producttray (product_id, tray_id)
VALUES (1, 1),
       (2, 1),
       (2, 2);
